from pathlib import Path
import json,html
OUT=Path(__file__).resolve().parent/'pbe15k_melting/attempt2/analysis';d=json.loads((OUT/'summary.json').read_text())
lines=['Плавление Ti: полный анализ PBE 15k и сравнение с 5k',
'Задача 20960770 завершена без ошибок: 04:31:57 на двух A100. Все четыре температуры (1700, 1750, 1800, 1850 K) содержат 40 ps подготовки и полные 50 ps production. Скопированы и проверены SHA256 132 файла (около 308 MB), включая все стадии траекторий, логи, данные и входные скрипты. Рестарты и скомпилированный потенциал сохранены на кластере.',
'Основной результат: для PBE 15k рабочая температурная скобка 1750–1800 K. При 1750 K кристалл растёт и жидкий слой исчезает; при 1800 K кристалл отступает и исчезает. Если нужен численный ориентир до уточнения, середина скобки равна 1775 K. Это не точечная оценка с доказанной точностью ±25 K и не доверительный интервал.',
'Температура | начальная доля solid-like | конечная | средняя за 40–50 ps | средняя T за 5–50 ps | среднее P (GPa)']
for T in [1700,1750,1800,1850]:
 s=d[f'15k_{T}'];lines.append(f"{T} K | {s['initial_fraction']:.4f} | {s['final_fraction']:.4f} | {s['mean_last10_fraction']:.4f} | {s['mean_T_5_50_K']:.2f} K | {s['mean_P_5_50_GPa']:.5f}")
lines+=['ДВИЖЕНИЕ ГРАНИЦ',
'1750 K: начальная ширина кристаллического слоя около 0.496 Lz. После начальных флуктуаций кристаллическая область расширяется. Последний разрешаемый двухфазный профиль обнаружен на 10.5 ps (ширина около 0.921 Lz); с 11 ps отдельный жидкий слой по этому критерию больше не разрешается. Доля solid-like затем флуктуирует вследствие теплового разупорядочения; на последних 10 ps её среднее равно 0.965, конечное значение 0.976. Условие f_s>0.90 без дальнейших кратких провалов выполняется с 34 ps: это другой диагностический показатель, а не время движения границы.',
'1800 K: исходная ширина кристаллического слоя 0.450 Lz; обе границы сближаются. Последний разрешаемый слой на 13 ps имеет ширину около 0.086 Lz; с 13.5 ps граница не определяется, а f_s<0.02 сохраняется с 14 ps до конца. Средняя доля solid-like на последних 10 ps составляет 0.000147. Образец остаётся жидким до 50 ps.',
'Исходы подтверждаются порогами qbar6=0.20, 0.25, 0.30, 0.35 и дополнительным критерием согласованных связей. Высокий порог 0.35 существенно недосчитывает термически разупорядоченный кристалл, поэтому абсолютную долю при нём не следует принимать за долю фазы. Для конечного упорядоченного образца 1750 K медиана qbar4=0.0347 совместима с bcc; это дополнительная проверка, не самостоятельная полная классификация структуры.',
'СРАВНЕНИЕ С PBE 5k',
'При одинаковых 1750 K оба checkpoint кристаллизуются. Начальные доли близки: 0.522 у 5k и 0.515 у 15k. Разрешаемая жидкая прослойка исчезает примерно к 19 ps у 5k и к 11 ps у 15k. Конечная доля в обеих реализациях 0.976; средние за последние 10 ps — 0.970 и 0.965.',
'При одинаковых 1800 K оба checkpoint плавятся. У 15k исходный кристаллический слой тоньше: 0.450 Lz против 0.505 Lz у 5k. Границы перестают разрешаться примерно к 13.5 ps и 18 ps соответственно. f_s<0.02 устойчиво выполняется с 14 ps у 15k и 18.5 ps у 5k. Ускоренное исчезновение слоя нельзя само по себе интерпретировать как изменение температуры плавления: отличаются исходные конфигурации, тепловой шум и потенциально кинетическая подвижность границ.',
'Для 5k прежняя рабочая скобка по направлению движения границ — 1750–1775 K; при 1775 K сначала границы флуктуируют, затем кристаллический слой сокращается, но к 50 ps ещё сохраняется (конечная f_s≈0.241). По противоположным однофазным исходам консервативная скобка 5k — те же 1750–1800 K. Новая серия 15k пока не имеет 1775 K и не даёт основания утверждать сдвиг Tm относительно прежнего ориентира около 1760 K. Нельзя сравнивать середину грубой скобки 15k (1775) с ориентиром 5k (1760) и объявлять повышение на 15 K.',
'ПРЕДЛОЖЕНИЕ ДЛЯ УТОЧНЕНИЯ',
'1. Приоритетная новая температура — 1775 K для 15k. Это середина текущей скобки и точка прямого сравнения с имеющейся пограничной траекторией 5k.',
'2. Вблизи границы желательно два независимо подготовленных образца с разными seed и production до 100 ps. Основание: у старого 5k при 1775 K направление движения менялось после примерно 25 ps. Один короткий начальный участок не даёт надёжной оценки стационарного движения.',
'3. Если при 1775 K воспроизводимо преобладает плавление, следующая точка 1760 K (или математическая середина 1762.5 K) для интервала 1750–1775 K. Если преобладает кристаллизация, следующая точка 1790 K (или середина 1787.5 K) для интервала 1775–1800 K. Если исходы противоположны или дрейф неразрешим, предпочтительнее дополнительные реплики/длинная траектория, затем 1765 и 1785 K, а не присвоение точного Tm=1775 K.',
'Новые расчёты в рамках этой проверки не запускались. Для двух 140 ps расчётов (40 ps подготовки +100 ps production), по одному на каждую A100, ориентир по текущей скорости около 3.5 часа; это оценка при доступности двух GPU, не обещание времени в очереди.',
'МЕТОД И ОГРАНИЧЕНИЯ',
'Использован прежний код audit/melting: 14 ближайших соседей с периодическими границами, усреднённый параметр Lechner–Dellago qbar6, основной порог 0.25. На каждой новой production-траектории сохранены 501 кадр через 0.1 ps; для сопоставления с архивом 5k структурный анализ выполнен на 101 кадре через 0.5 ps. Профиль по z/Lz: 36 слоёв, Gaussian smoothing sigma=1 слой для определения границ. Изменение размеров ячейки отделено от движения границ использованием приведённой координаты. После утраты двухфазности фиктивные границы не строятся (null в JSON).',
'Проверены идеальный bcc, полный набор шагов, конечные температуры, давления и устойчивость классификации. Средние T при 1750 и 1800 K составили 1748.93 и 1799.45 K; средние давления близки к заданным 0 bar (−0.00392 и −0.00044 GPa). Эти средние не заменяют оценки статистических и систематических ошибок.',
'Рабочие скобки относятся к одной ячейке 1296 атомов, одной подготовке на температуру и 50 ps наблюдения. Они не учитывают конечный размер, взаимодействие двух близких интерфейсов, ориентацию, межрепликовый разброс и систематические ошибки потенциала. Финальные тонкие слои не подходят для измерения стационарной скорости. Наклоны доли solid-like в summary.json лишь описательные: интервалы могут включать уже однофазную часть, поэтому по ним нельзя линейно экстраполировать Tm.',
'ФАЙЛЫ',
'summary.json — численные показатели, чувствительность порогов, термодинамические средние и SHA256 траекторий. 15k_*.npz — покадровые структурные показатели. solid_fraction_comparison — все температуры; matched_1750_1800 — сравнение долей и ширин при одинаковых T; interface_maps_comparison — карты границ. Исходные траектории и логи — ../collected/T*K/. Воспроизведение: collect_melting.py, analyze_melting_complete.py, report_melting_complete.py.']
text='\n\n'.join(lines);(OUT/'REPORT_RU.txt').write_text(text,encoding='utf-8')
imgs=''.join(f'<figure><img src="{n}.png"><figcaption><a href="{n}.pdf">PDF</a></figcaption></figure>' for n in ['solid_fraction_comparison','matched_1750_1800','interface_maps_comparison'])
body=''.join('<p>'+html.escape(s)+'</p>' for s in lines)
(OUT/'REPORT.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>Плавление Ti: 15k и 5k</title><style>body{font:16px/1.6 system-ui;max-width:1100px;margin:30px auto;padding:20px}img{width:100%}figure{margin:20px 0}a{color:#1678b5}</style><h1>Плавление Ti: PBE 15k и 5k</h1>'+imgs+'<p><a href="summary.json">Все численные результаты</a> · <a href="REPORT_RU.txt">Текст отчёта</a></p>'+body+'</html>',encoding='utf-8')
print(OUT/'REPORT.html')
